const saveEventResponse = `-- name: SaveEventResponse :exec
INSERT INTO event_responses (event_id, user_id, status, responded_by_id)
VALUES ($1, $2, $3::event_response_status, $4)
ON CONFLICT (event_id, user_id) DO UPDATE SET
    status = EXCLUDED.status, responded_by_id = EXCLUDED.responded_by_id, responded_at = now(),
    checked_in_at = NULL, checked_in_by_id = NULL
`

type SaveEventResponseParams struct {
	EventID       uuid.UUID           `json:"event_id"`
	UserID        uuid.UUID           `json:"user_id"`
	Status        EventResponseStatus `json:"status"`
	RespondedByID uuid.UUID           `json:"responded_by_id"`
}

func (q *Queries) SaveEventResponse(ctx context.Context, arg SaveEventResponseParams) error {
	_, err := q.db.Exec(ctx, saveEventResponse,
		arg.EventID,
		arg.UserID,
		arg.Status,
		arg.RespondedByID,
	)
	return err
}

const updateEvent = `-- name: UpdateEvent :one
UPDATE events e
SET title = $1, description = $2, event_type = $3,
    starts_at = $4, ends_at = $5, response_deadline = $6,
    capacity = $7, updated_at = clock_timestamp()
WHERE e.id = $8
  AND e.status = 'ACTIVE'
  AND e.starts_at > $9
  AND e.updated_at = $10
  AND ($7::integer IS NULL OR $7::integer >= (SELECT count(*) FROM event_responses r WHERE r.event_id = e.id AND r.status = 'Going'))
  AND ($3::text = 'COMPETITION' OR NOT EXISTS (SELECT 1 FROM competition_documents d WHERE d.event_id = e.id))
  AND (NOT $11::boolean OR NOT EXISTS (SELECT 1 FROM event_responses r WHERE r.event_id = e.id))
RETURNING id, title, description, event_type, starts_at, ends_at, response_deadline, capacity, status, cancelled_at, cancelled_by_id, cancellation_reason, created_by_id, created_at, updated_at
`

type UpdateEventParams struct {
	Title             string             `json:"title"`
	Description       string             `json:"description"`
	EventType         string             `json:"event_type"`
	StartsAt          pgtype.Timestamptz `json:"starts_at"`
	EndsAt            pgtype.Timestamptz `json:"ends_at"`
	ResponseDeadline  pgtype.Timestamptz `json:"response_deadline"`
	Capacity          *int32             `json:"capacity"`
	ID                uuid.UUID          `json:"id"`
	AsOf              pgtype.Timestamptz `json:"as_of"`
	ExpectedUpdatedAt pgtype.Timestamptz `json:"expected_updated_at"`
	AudienceChanged   bool               `json:"audience_changed"`
}

func (q *Queries) UpdateEvent(ctx context.Context, arg UpdateEventParams) (Event, error) {
	row := q.db.QueryRow(ctx, updateEvent,
		arg.Title,
		arg.Description,
		arg.EventType,
		arg.StartsAt,
		arg.EndsAt,
		arg.ResponseDeadline,
		arg.Capacity,
		arg.ID,
		arg.AsOf,
		arg.ExpectedUpdatedAt,
		arg.AudienceChanged,
	)
	var i Event
	err := row.Scan(
		&i.ID,
		&i.Title,
		&i.Description,
		&i.EventType,
		&i.StartsAt,
		&i.EndsAt,
		&i.ResponseDeadline,
		&i.Capacity,
		&i.Status,
		&i.CancelledAt,
		&i.CancelledByID,
		&i.CancellationReason,
		&i.CreatedByID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
